returns text
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  -- GS-01: the tokens a job refreshes live in Vault; only these names can be read, any other raises.
  if p_name not in ('meta_page_token', 'x_oauth_token', 'linkedin_oauth_token', 'job_runner_secret') then
